<?php class EmergencyController extends Controller{function index(){$this->view('emergency/index');}function report(){$db=Database::db();$q=$db->prepare('INSERT INTO emergency_incidents(reporter_user_id,type,description,latitude,longitude,address,status,severity) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$_SESSION['user']['id']??null,$_POST['type'],$_POST['description'],$_POST['latitude']?:null,$_POST['longitude']?:null,$_POST['address'],'reported',$_POST['severity']]);header('Location: emergency');}}